'use strict';
const DATA=[
 {name:'应用遍历与功能图',sub:'Desktop + Android · 规模化基础',cells:[['green','主流程已接通','发现、动作、观察更新与证据保存'],['amber','连续批次推进','已有桌面与 Android 局部连续记录'],['amber','统一清点待补','图身份、功能覆盖与未完成项继续核对']],status:'持续推进',detail:'10月6日桌面 Clock 批次保存99次模型调用、35个真实动作及其回执和后图；这是单应用有界运行，不是30个应用的全量验收。10月7日续批继续处理参数和功能总结，仍有身份与摘要缺口。',next:'以30个应用为覆盖冲刺范围；先核对已有材料与当前双端代表应用，再逐步扩量。尚无可信的“已验收应用数 / 目标应用数”统计。'},
 {name:'目标驱动任务生成',sub:'功能知识 → 自然用户目标',cells:[['green','普通入口已接通','读取冻结图，固定来源和引用'],['amber','单功能试点完成','已生成并执行城市查询目标'],['amber','批量质量待验证','补齐证据投影，验证复杂目标与条件']],status:'试点扩展',detail:'正常入口已由冻结 Clock 图生成 London 查询任务。10月6日周报指出部分已有控件/参数因缺功能整理字段未进入生成目录；该输入缺口及新跨区块支持的下游消费仍需核对。',next:'记录候选指令总数、拒绝原因、可执行性与复杂度；生成指令数不能当作成功轨迹数。没有提供批量目标的50%完成依据。'},
 {name:'实时轨迹采集',sub:'图指导执行 · 结果核验 · 轨迹保存',cells:[['green','单功能实机闭环','图 → 生成 → 执行 → 逐步记录'],['amber','小规模案例验证','已保留成功重跑与失败轮'],['gray','规模与吞吐待统计','独立核算尝试数、有效轨迹与成本']],status:'扩量准备',detail:'10月2日 London 查询重跑为8HTTP/2次GUI投递，另有wait新观察；含生成和首轮失败总计12HTTP/3GUI。该案例验证单功能闭环，不支持“有效轨迹已完成一半”。',next:'以3000条有效实机轨迹作为暂定严格目标；先测小批成功率、耗时、调用和人工续接，再判断扩量速度。'},
 {name:'Qwen3-VL 微调',sub:'Base / State-data / Region-data',cells:[['amber','训练方案已明确','固定划分与可比数据 / 训练预算'],['gray','小批训练待接通','导出、更新、checkpoint重载'],['gray','正式训练待开展','保留数据版本、配置与训练记录']],status:'待开展',gray:true,detail:'现有计划明确比较原模型、State数据微调、Region数据微调。旧训练入口不能作为Qwen3-VL已完成训练的证明；当前资料未给出新训练完成记录。',next:'先用小批合格轨迹核对格式和重载，训练前隔离正式测试任务；不能仅删除Region字段构造State对照。'},
 {name:'下游主评测',sub:'OSWorld + AndroidWorld',cells:[['amber','部分基线可复用','OSWorld历史 runner 与记录已找到'],['gray','统一新协议待执行','AndroidWorld接线继续核验'],['gray','主结果表待回填','同条件评测三组模型']],status:'接线准备',gray:true,detail:'计划保留OSWorld既有Qwen3-VL历史评测作为复用基础，但历史批次存在评分与协议差异；AndroidWorld接线尚待验证，MobileWorld不能替代。',next:'固定相同任务、初态、动作能力与测试时信息，保存逐任务结果；测试时额外图信息不能混入训练数据收益。'},
 {name:'核心对照与论文',sub:'表示 / 生成 / 采集 · 方法与结果',cells:[['green','方法稿与协议已有','已有论文工作稿，可先讨论方法'],['amber','实验设计已列出','对照组与指标沿原计划推进'],['gray','比较结果待形成','主实验、消融、成本与失败分析']],status:'方案就绪',detail:'已有15页方法工作稿及实验协议，但实验数字和结果仍有占位。四组实验是主训练评测、Region表示效率、目标先行生成、图指导实时采集。',next:'同步更新方法和实验设计；只填已获得结果，10月11日和18日按实测产出重新估算规模与进度。'}
];
const PLANS=[['E1 · 主实验','训练与泛化','原模型 / State 数据微调 / Region 数据微调；在 OSWorld 与 AndroidWorld 同条件评测。','任务成功率 · 同预算数据与训练'],['E2 · 表示对照','Region 与探索效率','相同应用、初态和预算，比较 State 与 Region 表示；核对重复探索及身份错误。','功能核验 · 图质量 · 调用成本'],['E3 · 生成对照','目标组合与任务质量','比较 Screen/trajectory-first、单功能有依据、完整目标先行组合。','自然性 · 可执行性 · 复杂度'],['E4 · 采集对照','图指导与实时执行','固定任务及初态，比较无图、State 图、Region 图及相关经验指导。','业务成功 · 失败类型 · 摊销成本']];
document.querySelector('#rows').innerHTML=DATA.map((d,i)=>`<tr tabindex="0" role="button" aria-label="查看${d.name}的进度依据" data-index="${i}"><td><div class="work"><strong>${d.name}</strong><small>${d.sub}</small></div></td>${d.cells.map(([c,t,n])=>`<td><div class="stage"><div class="stage-title">${t}</div><div class="bar ${c}"></div><p>${n}</p></div></td>`).join('')}<td><div class="status"><span class="badge ${d.gray?'gray':''}">${d.status}</span><span class="arrow">↗</span></div></td></tr>`).join('');
document.querySelector('#plans').innerHTML=PLANS.map(([id,title,body,measure])=>`<article class="plan-item"><small>${id}</small><h3>${title}</h3><p>${body}</p><p class="measure">${measure}</p></article>`).join('');
function show(i){const d=DATA[i];document.querySelector('#detailTitle').textContent=d.name;document.querySelector('#detailBody').innerHTML=`<p><b>已有依据</b><br>${d.detail}</p><p><b>下一步与统计口径</b><br>${d.next}</p><p><a href="progress-sources.html">查看本页采用的报告与计划 ↗</a></p>`;document.querySelector('#detail').showModal();}
document.querySelectorAll('[data-index]').forEach(el=>{el.onclick=()=>show(+el.dataset.index);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(+el.dataset.index);}};});
document.querySelector('#close').onclick=()=>document.querySelector('#detail').close();document.querySelector('#print').onclick=()=>window.print();

const DATASETS=[
 ['AndroidControl','Android · NeurIPS 2024',15283,5.5,'https://papers.neurips.cc/paper_files/paper/2024/file/a79f3ef3b445fd4659f44648f7ea8ffd-Paper-Datasets_and_Benchmarks_Track.pdf'],
 ['GUIOdyssey','Android · arXiv v2 / 2025',8334,15.3,'https://arxiv.org/html/2406.08451v2'],
 ['Mind2Web','Web · arXiv v2 / 2023',2350,7.3,'https://arxiv.org/html/2306.06070v2']
];
document.querySelector('#datasetRows').innerHTML=DATASETS.map(([name,platform,count,steps,url])=>`<div class="dataset-row"><div><strong><a href="${url}" target="_blank" rel="noopener">${name} ↗</a></strong><small>${platform}</small></div><div><div class="quantity"><i class="published" style="width:${count/160}%"></i></div><b>${count.toLocaleString('en-US')}</b><small>论文全量演示 / episode</small></div><div class="step-value"><strong>${steps.toFixed(1)} <em>步</em></strong><div class="step-track"><i style="width:${steps/16*100}%"></i></div></div></div>`).join('');
